]


def _strip_links(text):
    text = re.sub(r"!\[([^\]]*)\]\([^)]*\)", r"\1", text)  # images
    return re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", text)  # links


def _strip_markup(text):
    """Remove HTML tags and emphasis from text that has no code spans."""
    text = HTML_TAG_RE.sub("", text)
    for rx in EMPHASIS_RES:
        text = rx.sub(r"\1", text)
    return text


def _segments(text):
    """Split text into (is_code, raw, content) pieces around code spans."""
    pos = 0
    for m in CODE_SPAN_RE.finditer(text):
        if m.start() > pos:
            yield False, text[pos:m.start()], text[pos:m.start()]
        content = m.group(2)
        if content.startswith(" ") and content.endswith(" ") and content.strip():
            content = content[1:-1]
        yield True, m.group(0), content
        pos = m.end()
    if pos < len(text):
        yield False, text[pos:], text[pos:]


def strip_inline(text):
    """Plain text of a heading, as GitHub uses it to build the anchor.

    Code span contents are kept literally (no emphasis or tag stripping).
    """
    parts = []
    for is_code, _, content in _segments(_strip_links(text)):
        parts.append(content if is_code else _strip_markup(content))
    return "".join(parts).strip()


def toc_label(text):
    """Link text for the TOC: markup removed, code spans kept, brackets escaped."""
    parts = []
    for is_code, raw, _ in _segments(_strip_links(text)):
        if is_code:
            parts.append(raw)
        else:
            parts.append(re.sub(r"([\[\]])", r"\\\1", _strip_markup(raw)))
    return "".join(parts).strip()


