def replace_toc(text, toc):
    """Replace the lines between the marker lines with toc.

    Markers count only on a line of their own and outside fenced code, so
    examples like `<!-- toc -->` in prose or code blocks are never touched.
    """
    lines = text.splitlines(keepends=True)
    start = end = None
    for i, line in iter_lines_outside_fences([l.rstrip("\r\n") for l in lines]):
        if start is None and line.strip() == TOC_START:
            start = i
        elif start is not None and line.strip() == TOC_END:
            end = i
            break
    if start is None or end is None:
        raise ValueError(f"markers {TOC_START} and {TOC_END} not found")
    before = "".join(lines[: start + 1])
    if not before.endswith("\n"):
        before += "\n"
    return f"{before}\n{toc}\n{''.join(lines[end:])}"

