AUTOLINK_RE = re.compile(
    r"<([A-Za-z][A-Za-z0-9+.-]{1,31}:[^\s<>]*"  # <https://...>
    r"|[\w.!#$%&'*+/=?^{|}~-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*)>")  # <user@example.com>
HTML_RE = re.compile(r"<!--.*?-->|</?[A-Za-z][A-Za-z0-9-]*(?:\s[^<>]*)?/?>")
_TEXT = r"((?:[^\[\]]|\[[^\[\]]*\])*)"  # link text, one level of nested []
_DEST = r"\((?:[^()\\]|\\.|\((?:[^()\\]|\\.)*\))*\)"  # (url "title"), nested ()
INLINE_LINK_RE = re.compile(r"(!?)\[" + _TEXT + r"\]" + _DEST)
REF_LINK_RE = re.compile(r"(!?)\[" + _TEXT + r"\](?:\[([^\[\]]*)\])?")
REF_DEF_RE = re.compile(r"^ {0,3}\[([^\[\]]+)\]:[ \t]*\S")
ENTITY_RE = re.compile(r"&(?:#[0-9]{1,7}|#[xX][0-9a-fA-F]{1,6}|[A-Za-z][A-Za-z0-9]{1,31});")
EMOJI_RE = re.compile(r":([a-z0-9_+-]+):")
# Emphasis and strikethrough must hug their text; "_" cannot open or close
