def _render_inline(text, refs, for_label):
    """Reduce inline Markdown to plain text.

    for_label=False gives the text GitHub slugs. for_label=True gives safe
    link text for the TOC: code spans, escapes, entities and emoji shortcodes
    are kept as written, and stray [ ] are escaped.
    """
    codes = []

    def code(m):
        content = m.group(2)
        if content.startswith(" ") and content.endswith(" ") and content.strip():
            content = content[1:-1]
        codes.append(m.group(0) if for_label else content)
        return chr(_CODE_BASE + len(codes) - 1)

    text = CODE_SPAN_RE.sub(code, text)
    text = ESCAPE_RE.sub(lambda m: chr(_ESC_BASE + ord(m.group(1))), text)
    text = AUTOLINK_RE.sub(r"\1", text)
    text = HTML_RE.sub("", text)

    def link(m, label=None):
        if m.group(1):  # image: rendered as <img>, which has no text
            return m.group(2) if for_label else ""
        return m.group(2)

    def ref_link(m):
        ref = m.group(3) or m.group(2)  # [text][ref], [text][] or [text]
        if _norm_ref(ref) not in refs:
            return m.group(0)  # undefined: GitHub shows it literally
        return link(m)

    text = INLINE_LINK_RE.sub(link, text)
    text = REF_LINK_RE.sub(ref_link, text)
    for rx in EMPHASIS_RES:
        text = rx.sub(r"\1", text)
    if for_label:
        text = re.sub(r"([\[\]])", r"\\\1", text)
    else:
        text = EMOJI_RE.sub(
            lambda m: "" if _is_emoji(m.group(1)) else m.group(0), text)
        text = ENTITY_RE.sub(lambda m: html.unescape(m.group(0)), text)

    def restore(ch):
        n = ord(ch)
        if _CODE_BASE <= n < _CODE_BASE + len(codes):
            return codes[n - _CODE_BASE]
        if _ESC_BASE <= n < _ESC_BASE + 128:
            return ("\\" if for_label else "") + chr(n - _ESC_BASE)
        return ch

    return "".join(restore(c) for c in text).strip()


